1	import { useEffect, useRef, useState } from "react";
2	import { useReducedMotion } from "motion/react";
3	import type { ResponseBlock } from "./conversationContent";
4	
5	const CHUNK_INTERVAL_MS = 25;
6	const CHUNK_JITTER_MS = 20;
7	/** Extra pause before a new block starts, mimicking the visible beat
8	 * between paragraphs/bullets in real streamed responses. */
9	const BLOCK_PAUSE_MS = 150;
10	const BLOCK_PAUSE_JITTER_MS = 100;
11	const MIN_WORDS_PER_CHUNK = 1;
12	const MAX_WORDS_PER_CHUNK = 4;
13	
14	/** Splits a block into the ordered list of reveal steps within it — words
15	 * for prose blocks, whole lines for diff blocks (revealing a diff
16	 * word-by-word would look wrong; each line lands as a unit). */
17	function blockUnitCount(block: ResponseBlock): number {
18	  if (block.type === "diff") return block.lines.length;
19	  return block.text.split(/\s+/).filter(Boolean).length;
20	}
21	
22	export interface UseStreamingRevealResult {
23	  /** For each block, how many words (or diff lines) are currently revealed. -1 means the block hasn't started yet. */
24	  revealedPerBlock: number[];
25	  isDone: boolean;
26	}
27	
28	/**
29	 * Reveals `blocks` in order, word-by-word within prose blocks and
30	 * line-by-line within diff blocks, in fast randomized chunks rather than
31	 * one-at-a-time — mimics how streamed LLM output actually renders (bursts
32	 * of a few tokens at once), which reads as much faster than character-by-
33	 * character typing for the same amount of content. Starts only once
34	 * `start` becomes true (the caller sequences this after the prompt line
35	 * finishes) and runs once.
36	 */
37	export function useStreamingReveal(
38	  blocks: ResponseBlock[],
39	  start: boolean,
40	): UseStreamingRevealResult {
41	  const shouldReduceMotion = useReducedMotion();
42	  const [revealedPerBlock, setRevealedPerBlock] = useState<number[]>(() =>
43	    blocks.map(() => -1),
44	  );
45	  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
46	  const hasStartedRef = useRef(false);
47	
48	  useEffect(() => {
49	    if (!start || hasStartedRef.current) return;
50	    hasStartedRef.current = true;
51	
52	    const totalUnitsPerBlock = blocks.map(blockUnitCount);
53	
54	    if (shouldReduceMotion) {
55	      const id = setTimeout(() => {
56	        setRevealedPerBlock(totalUnitsPerBlock.map((n) => n));
57	      }, 0);
58	      return () => clearTimeout(id);
59	    }
60	
61	    let blockIndex = 0;
62	    let unitsRevealed = 0;
63	    const progress: number[] = blocks.map(() => -1);
64	
65	    const revealNext = () => {
66	      if (blockIndex >= blocks.length) return;
67	
68	      const block = blocks[blockIndex];
69	      const totalUnits = totalUnitsPerBlock[blockIndex];
70	      const isDiffBlock = block.type === "diff";
71	
72	      const chunkSize = isDiffBlock
73	        ? 1
74	        : Math.min(
75	            totalUnits - unitsRevealed,
76	            MIN_WORDS_PER_CHUNK +
77	              Math.floor(Math.random() * (MAX_WORDS_PER_CHUNK - MIN_WORDS_PER_CHUNK + 1)),
78	          );
79	
80	      unitsRevealed += chunkSize;
81	      progress[blockIndex] = unitsRevealed;
82	      setRevealedPerBlock([...progress]);
83	
84	      if (unitsRevealed >= totalUnits) {
85	        blockIndex += 1;
86	        unitsRevealed = 0;
87	        if (blockIndex >= blocks.length) return;
88	        const delay = BLOCK_PAUSE_MS + Math.random() * BLOCK_PAUSE_JITTER_MS;
89	        timeoutRef.current = setTimeout(revealNext, delay);
90	        return;
91	      }
92	
93	      const delay = CHUNK_INTERVAL_MS + Math.random() * CHUNK_JITTER_MS;
94	      timeoutRef.current = setTimeout(revealNext, delay);
95	    };
96	
97	    revealNext();
98	
99	    return () => {
100	      if (timeoutRef.current) clearTimeout(timeoutRef.current);
101	    };
102	  }, [start, shouldReduceMotion, blocks]);
103	
104	  const isDone =
105	    revealedPerBlock.length > 0 &&
106	    revealedPerBlock.every((count, i) => count >= blockUnitCount(blocks[i]));
107	
108	  return { revealedPerBlock, isDone };
109	}
